<?php declare(strict_types=1);
namespace Kulturhus\Verein;
use PDO;use DomainException;
final class ClubChat {
 public function __construct(private PDO $db,private string $actor){}
 private function authority():array{$a=Permissions::actor($this->db,$this->actor);if($a['role']==='editor')throw new DomainException('Kein Chat-Zugriff.');return $a;}
 public function directory():array{$a=$this->authority();$rows=DocumentCatalog::query($this->db,"SELECT a.id,COALESCE(c.name,a.id) name FROM actors a LEFT JOIN contacts c ON c.club_id=a.club_id AND c.id=a.contact_id WHERE a.club_id=? AND a.active=1 AND a.role!='editor' AND (a.contact_id IS NULL OR c.archived_at IS NULL) ORDER BY name",[$a['club_id']])->fetchAll();return ActorNames::rows($this->db,$a['club_id'],array_values(array_filter($rows,function($r){try{Permissions::actor($this->db,$r['id']);return true;}catch(DomainException){return false;}})));}
 public function thread(string $id):array{$a=$this->authority();$r=DocumentCatalog::query($this->db,'SELECT c.* FROM club_chats c JOIN club_chat_people p ON p.chat_id=c.id WHERE c.club_id=? AND c.id=? AND p.actor_id=?',[$a['club_id'],$id,$a['id']])->fetch();if(!$r)throw new DomainException('Unterhaltung nicht verfügbar.');return $r;}
 public function listing():array{$a=$this->authority();return DocumentCatalog::query($this->db,'SELECT c.*, (SELECT COUNT(*) FROM club_chat_messages m WHERE m.chat_id=c.id AND m.seq>p.last_read AND m.actor_id!=p.actor_id) unread FROM club_chats c JOIN club_chat_people p ON p.chat_id=c.id WHERE c.club_id=? AND p.actor_id=? ORDER BY (SELECT MAX(seq) FROM club_chat_messages WHERE chat_id=c.id) DESC,c.created_at DESC',[$a['club_id'],$a['id']])->fetchAll();}
 public function create(string $title,array $people):string{$a=$this->authority();$title=trim($title);$people=array_values(array_unique([...$people,$a['id']]));if($title===''||strlen($title)>150||count($people)<2||count($people)>50||array_diff($people,array_column($this->directory(),'id')))throw new DomainException('Titel und zwei bis 50 aktive Teilnehmer wählen.');$this->db->beginTransaction();try{$this->authority();$id=bin2hex(random_bytes(16));DocumentCatalog::query($this->db,'INSERT INTO club_chats VALUES(?,?,?,?,?)',[$id,$a['club_id'],$title,$a['id'],gmdate('c')]);foreach($people as $person)DocumentCatalog::query($this->db,'INSERT INTO club_chat_people(chat_id,actor_id) VALUES(?,?)',[$id,$person]);$this->db->commit();return $id;}catch(\Throwable $e){$this->db->rollBack();throw $e;}}
 public function messages(string $id,int $before=PHP_INT_MAX):array{$thread=$this->thread($id);return ActorNames::rows($this->db,$thread['club_id'],array_reverse(DocumentCatalog::query($this->db,"SELECT m.seq,m.actor_id,m.body,m.created_at,m.file_name,COALESCE((SELECT MAX(h.sequence) FROM audit_events h WHERE h.club_id=a.club_id AND h.action='chat.message.edited' AND h.object_id=CAST(m.seq AS CHAR)),0) edit_revision,COALESCE(c.name,m.actor_id) name FROM club_chat_messages m JOIN actors a ON a.id=m.actor_id LEFT JOIN contacts c ON c.club_id=a.club_id AND c.id=a.contact_id WHERE m.chat_id=? AND m.seq<? ORDER BY m.seq DESC LIMIT 200",[$id,$before])->fetchAll()),'actor_id');}
 public function read(string $id,int $through):void{$this->thread($id);DocumentCatalog::query($this->db,'UPDATE club_chat_people SET last_read=GREATEST(last_read,?) WHERE chat_id=? AND actor_id=?',[$through,$id,$this->actor]);}
 public function send(string $id,string $body,string $key,?array $file=null):void{$this->thread($id);$body=trim($body);if(($body===''&&!$file)||strlen($body)>5000||str_contains($body,"\0")||!preg_match('/^[a-f0-9]{32}$/D',$key))throw new DomainException('Nachricht bis 5.000 Zeichen eingeben.');$name=$mime=$bytes=null;if($file){[$name,$mime]=Documents::inspectFile($file['name'],$file['bytes']);$bytes=$file['bytes'];if(strlen($bytes)>2097152||!in_array($mime,['application/pdf','image/png','image/jpeg'],true))throw new DomainException('Chat-Anhang: PDF, PNG oder JPG bis 2 MB.');} $this->db->beginTransaction();try{$this->thread($id);$old=DocumentCatalog::query($this->db,'SELECT * FROM club_chat_messages WHERE request_key=?',[$key])->fetch();if($old){if($old['chat_id']!==$id||$old['actor_id']!==$this->actor||$old['body']!==$body||$old['file_bytes']!==$bytes)throw new DomainException('Nachrichtenkennung bereits verwendet.');}else{DocumentCatalog::query($this->db,'INSERT INTO club_chat_messages(chat_id,actor_id,body,created_at,request_key,file_name,file_mime,file_bytes) VALUES(?,?,?,?,?,?,?,?)',[$id,$this->actor,$body,gmdate('c'),$key,$name,$mime,$bytes]);PushNotifications::enqueue($this->db,(int)$this->db->lastInsertId());}$this->db->commit();}catch(\Throwable $e){$this->db->rollBack();throw $e;}}
 public function file(string $id,int $seq):array{$this->thread($id);$r=DocumentCatalog::query($this->db,'SELECT file_name name,file_mime mime,file_bytes bytes FROM club_chat_messages WHERE chat_id=? AND seq=? AND file_bytes IS NOT NULL',[$id,$seq])->fetch();if(!$r)throw new DomainException('Anhang nicht verfügbar.');return $r;}
 public function leave(string $id):void{$this->thread($id);DocumentCatalog::query($this->db,'DELETE FROM club_chat_people WHERE chat_id=? AND actor_id=?',[$id,$this->actor]);}
 public function people(string $id):array{$thread=$this->thread($id);return ActorNames::rows($this->db,$thread['club_id'],DocumentCatalog::query($this->db,'SELECT p.actor_id id,COALESCE(c.name,p.actor_id) name FROM club_chat_people p JOIN actors a ON a.id=p.actor_id LEFT JOIN contacts c ON c.club_id=a.club_id AND c.id=a.contact_id WHERE p.chat_id=? ORDER BY name',[$id])->fetchAll());}
 public function addPeople(string $id,array $people):void
 {
  $this->db->beginTransaction();try{$thread=$this->thread($id);if($thread['owner']!==$this->actor)throw new DomainException('Nur die erstellende Person kann Teilnehmer hinzufügen.');$known=array_column($this->people($id),'id');$people=array_values(array_diff(array_unique($people),$known));if(!$people){$this->db->commit();return;}if(count($known)+count($people)>50||array_diff($people,array_column($this->directory(),'id')))throw new DomainException('Höchstens 50 aktive Teilnehmer desselben Vereins wählen.');foreach($people as $person)DocumentCatalog::query($this->db,'INSERT INTO club_chat_people(chat_id,actor_id) VALUES(?,?)',[$id,$person]);$this->db->commit();}catch(\Throwable $e){$this->db->rollBack();throw $e;}
 }
 public static function editToken(array $message):string{return hash('sha256',$message['seq'].':'.$message['body'].':'.($message['edit_revision']??0));}
 public function editMessage(string $id,int $seq,string $body,string $token):void
 {
  $body=trim($body);if(strlen($body)>5000||str_contains($body,"\0"))throw new DomainException('Nachricht bis 5.000 Zeichen eingeben.');
  $this->db->beginTransaction();try{$this->thread($id);$message=null;foreach($this->messages($id,$seq+1) as $row)if((int)$row['seq']===$seq)$message=$row;
   if(!$message||$message['actor_id']!==$this->actor)throw new DomainException('Nur eigene Nachrichten können bearbeitet werden.');
   if(DocumentCatalog::query($this->db,'SELECT 1 FROM club_chat_polls WHERE message_seq=?',[$seq])->fetchColumn())throw new DomainException('Eine veröffentlichte Umfrage kann nicht verändert werden. Bitte bei Bedarf beenden und eine neue Umfrage erstellen.');
   if(!hash_equals(self::editToken($message),$token))throw new DomainException('Nachricht inzwischen geändert. Bitte neu laden.');if($body===''&&!$message['file_name'])throw new DomainException('Nachricht darf nicht leer sein.');
   if($message['body']!==$body){$a=$this->authority();DocumentCatalog::query($this->db,'UPDATE club_chat_messages SET body=? WHERE chat_id=? AND seq=? AND actor_id=?',[$body,$id,$seq,$this->actor]);DocumentCatalog::query($this->db,'INSERT INTO audit_events(club_id,actor_id,action,object_id,object_version,happened_at) VALUES(?,?,?,?,?,?)',[$a['club_id'],$a['id'],'chat.message.edited',(string)$seq,(int)$message['edit_revision']+1,gmdate('c')]);}$this->db->commit();
  }catch(\Throwable $e){$this->db->rollBack();throw $e;}
 }
}
